package com.bookmarked.storage;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Path;

/**
 * Private file storage. Keys are generated by the app (never taken from users),
 * e.g. {@code ebooks/3f2c….pdf}. Locally this is a folder; at deployment an
 * S3/R2 implementation takes its place without the callers changing.
 */
public interface FileStorage {

    /** Copies {@code source} to {@code key}, replacing anything already there. */
    void put(String key, Path source) throws IOException;

    void put(String key, byte[] content) throws IOException;

    InputStream open(String key) throws IOException;

    long size(String key) throws IOException;

    boolean exists(String key);

    void delete(String key);
}
